from collections import Counter
import re

class NLPDataProcessor2:

    TOP_N_WORDS = 5

    def process_data(self, string_list):
        def process_string(s):
            processed_string = re.sub(r'[^a-zA-Z\s]', '', s.lower())
            return processed_string.split()
        return [process_string(string) for string in string_list]

    def calculate_word_frequency(self, words_list):
        word_frequency = Counter()
        for words in words_list:
            word_frequency.update(words)
        sorted_word_frequency = sorted(word_frequency.items(), key=lambda x: x[1], reverse=True)
        top_n_word_frequency = dict(sorted_word_frequency[:self.TOP_N_WORDS])
        return top_n_word_frequency

    def process(self, string_list):
        return self.calculate_word_frequency(self.process_data(string_list))
